<?php
require __DIR__.'/layout_start.php';if($_SERVER['REQUEST_METHOD']==='POST'){$id=sanitize_int($_POST['id'] ?? 0,0);$status=sanitize_text($_POST['status'] ?? '',50);$valid=['Pendente','Pago','Enviado','Entregue','Cancelado'];if(in_array($status,$valid,true)){db()->prepare('UPDATE tbl_Vendas SET StatusVenda=? WHERE ID_Venda=?')->execute([$status,$id]);flash('success','Status do pedido atualizado.');redirect('pedidos.php');}}$orders=db()->query("SELECT v.*,c.Nome_Cliente,c.Sobr_Cliente,c.Email_Cliente,f.NomeForma FROM tbl_Vendas v JOIN tbl_Clientes c ON c.ID_Cliente=v.ID_Cliente LEFT JOIN tbl_FormaPagamento f ON f.ID_Forma=v.ID_Forma ORDER BY v.DataVenda DESC")->fetchAll(); ?>
<div class="admin-head"><div><div class="eyebrow">OPERAÇÃO</div><h1>Pedidos.</h1></div></div><?php if($orders): ?><table class="data-table"><tr><th>Pedido</th><th>Cliente</th><th>Pagamento</th><th>Data</th><th>Total</th><th>Status</th></tr><?php foreach($orders as $o): ?><tr><td>#<?= $o['ID_Venda'] ?></td><td><?= e($o['Nome_Cliente'].' '.$o['Sobr_Cliente']) ?><br><small><?= e($o['Email_Cliente']) ?></small></td><td><?= e($o['NomeForma']??'—') ?></td><td><?= date('d/m/Y H:i',strtotime($o['DataVenda'])) ?></td><td><?= money((float)$o['ValorTotal']) ?></td><td><form method="post"><input type="hidden" name="id" value="<?= $o['ID_Venda'] ?>"><select name="status" onchange="this.form.submit()" style="background:#171020;color:#fff;border:1px solid #453253;border-radius:4px;padding:6px"><option <?= $o['StatusVenda']==='Pendente'?'selected':'' ?>>Pendente</option><option <?= $o['StatusVenda']==='Pago'?'selected':'' ?>>Pago</option><option <?= $o['StatusVenda']==='Enviado'?'selected':'' ?>>Enviado</option><option <?= $o['StatusVenda']==='Entregue'?'selected':'' ?>>Entregue</option><option <?= $o['StatusVenda']==='Cancelado'?'selected':'' ?>>Cancelado</option></select></form></td></tr><?php endforeach; ?></table><?php else: ?><div class="empty">Ainda não há pedidos.</div><?php endif; ?><?php require __DIR__.'/layout_end.php'; ?>
